:root:not([data-theme="light"]) .bt2{--bd-bg:#243140;--bd-fg:#e3edf7;--bd-seg:#a3bad1;--bd-off:#25303b}
:root:not([data-theme="light"]) .bt3{--bd-bg:#3a321c;--bd-fg:#f3d27a;--bd-seg:#d9aa35;--bd-off:#33301f}
:root:not([data-theme="light"]) .bt4{--bd-bg:#2b2f45;--bd-fg:#c9cff2;--bd-seg:#8592d0;--bd-off:#292c3a}
:root:not([data-theme="light"]) .bt5{--bd-bg:#16334a;--bd-fg:#a6e0fb;--bd-seg:#3aa9de;--bd-off:#1c2c38}
:root:not([data-theme="light"]) .btr{--bd-bg:#2f2350;--bd-fg:#d6c2ff;--bd-seg:#9a73f5;--bd-off:#2b2540}}
:root[data-theme="dark"] .bt1{--bd-bg:#3a2a1f;--bd-fg:#f0bf95;--bd-seg:#cf8a52;--bd-off:#33281f}
:root[data-theme="dark"] .bt2{--bd-bg:#243140;--bd-fg:#e3edf7;--bd-seg:#a3bad1;--bd-off:#25303b}
:root[data-theme="dark"] .bt3{--bd-bg:#3a321c;--bd-fg:#f3d27a;--bd-seg:#d9aa35;--bd-off:#33301f}
:root[data-theme="dark"] .bt4{--bd-bg:#2b2f45;--bd-fg:#c9cff2;--bd-seg:#8592d0;--bd-off:#292c3a}
:root[data-theme="dark"] .bt5{--bd-bg:#16334a;--bd-fg:#a6e0fb;--bd-seg:#3aa9de;--bd-off:#1c2c38}
:root[data-theme="dark"] .btr{--bd-bg:#2f2350;--bd-fg:#d6c2ff;--bd-seg:#9a73f5;--bd-off:#2b2540}
.bd.ghost{opacity:.55}
.nb-dot{position:absolute;top:1px;right:8px;width:8px;height:8px;border-radius:50%;background:var(--blunder);box-shadow:0 0 0 2px var(--surface)}
.pnb-head{display:flex;align-items:center;gap:14px}
.pnb-rank{display:block;transition:transform .25s var(--ease)} .pnb-rank:hover{transform:scale(1.05) rotate(-3deg)}
.pnb{display:flex;gap:4px;flex-wrap:wrap}
.pnb-i{display:block;transition:transform .2s var(--ease)} .pnb-i:hover{transform:translateY(-3px) rotate(-4deg)}
.bbar{height:8px;border-radius:99px;background:var(--surface-2);overflow:hidden}
.bbar i{display:block;height:100%;background:linear-gradient(90deg,var(--accent),#e5c25a);transform-origin:left;transition:transform .7s var(--ease)}
.bbar.sm{height:5px;width:100%} .bbar.lg{height:10px;width:100%;max-width:520px}
.cq-hero{display:flex;flex-direction:column;gap:18px;overflow:hidden;position:relative}
.cq-hero-in{display:flex;align-items:center;gap:18px;position:relative}
.cq-emb{flex:none;animation:embIn .8s cubic-bezier(.2,1.4,.3,1) both}
@keyframes embIn{from{transform:scale(.6) rotate(-12deg);opacity:0}}
.cq-rank{font:800 30px/1.05 var(--f-display);letter-spacing:-.02em}
.cq-ladder{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:4px;position:relative}
.cq-ladder::before{content:"";position:absolute;left:8%;right:8%;top:23px;height:2px;background:var(--line)}
.cq-step{display:flex;flex-direction:column;align-items:center;gap:2px;position:relative;font-size:11.5px;color:var(--muted)}
.cq-step .bd{width:46px;height:46px}
.cq-step span:first-of-type{font-weight:700;color:var(--ink)} .cq-step .mono{font-size:10.5px}
.cq-step.cur .bd{transform:scale(1.15)}
.cq-step.cur span:first-of-type{color:var(--accent-ink)}
.cq-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.cq-stats div{display:flex;flex-direction:column;gap:2px;padding:10px 12px;border-radius:12px;background:var(--surface-2)}
.cq-stats b{font:800 20px var(--f-display);font-variant-numeric:tabular-nums} .cq-stats small{font-size:12px;color:var(--muted);font-weight:600}
.cq-stats span{font-size:12px;color:var(--muted)}
.cq-near{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:8px}
.cq-n{display:flex;align-items:center;gap:12px;padding:10px 12px;border:1px solid var(--line);border-radius:14px;background:var(--surface);font-size:14px;color:var(--ink);transition:border-color .2s}
.cq-n:hover{border-color:var(--accent)}
.cq-cat{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap} .cq-cat .muted{font-size:13px}
.cq-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(168px,1fr));gap:10px}
.cq{display:flex;flex-direction:column;align-items:center;gap:4px;padding:18px 12px 14px;border:1px solid var(--line);border-radius:16px;background:var(--surface);text-align:center;color:var(--ink);transition:border-color .2s,background-color .2s}
.cq:hover{border-color:color-mix(in srgb,var(--ink) 25%,var(--line))} .cq.flash{border-color:var(--accent);background:var(--accent-soft)}
.cq b{font-size:14.5px;line-height:1.25} .cq .bd{margin-bottom:4px}

.cq-t{font:700 10.5px var(--f-display);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.cq.got .cq-t{color:var(--ink)}
.cq-d{font-size:12px;line-height:1.35}
.cq-more{display:none;flex-direction:column;gap:5px;text-align:left;font-size:12px;line-height:1.35;color:var(--muted);width:100%;border-top:1px solid var(--line);padding-top:9px;margin-top:4px}
.cq.open .cq-more{display:flex} .cq-more .ok{color:var(--best-ink)} .cq-more b{color:var(--ink);font-size:12px}
.tag.tier-1{background:#f3e4d7;color:#8f5226} .tag.tier-2{background:#e1e9f1;color:#33485e} .tag.tier-3{background:#f8edcc;color:#7f5a07}
.tag.tier-4{background:#e5e7f4;color:#38426e} .tag.tier-5{background:#dcf0f9;color:#0f587f} .tag.tier-r{background:#ede4fc;color:#5524a8}
@media (max-width:520px){
  .cq-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px} .cq{padding:12px 8px} .cq .bd{width:76px;height:76px}
  .cq-hero-in{gap:12px} .cq-emb .bd{width:104px;height:104px} .cq-rank{font-size:25px}
  .cq-stats{gap:6px} .cq-stats div{padding:8px 8px} .cq-stats b{font-size:16px} .cq-stats small{font-size:11px} .cq-stats span{font-size:11px}
  .cq-step{font-size:10.5px} .cq-step .bd{width:38px;height:38px} .cq-ladder::before{top:19px}
}
.bfx-card.promo h2{font-size:26px}
.bfx{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;padding:16px;background:rgba(5,9,7,.62);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);opacity:0;transition:opacity .22s var(--ease)}
.bfx.on{opacity:1}
.bfx-card{position:relative;overflow:hidden;width:min(360px,100%);display:flex;flex-direction:column;align-items:center;gap:10px;padding:26px 22px 22px;border-radius:24px;background:var(--surface);color:var(--ink);text-align:center;box-shadow:0 30px 80px rgba(0,0,0,.45);transform:scale(.9) translateY(10px);transition:transform .35s cubic-bezier(.2,1.3,.3,1)}
.bfx.on .bfx-card{transform:none}
