.bfx-card p{font-size:14.5px;line-height:1.45}
.bfx-badge{width:150px;height:150px;margin:6px 0 4px;animation:badgeIn .55s cubic-bezier(.2,1.25,.3,1) both .05s}
.bfx-badge .bd{width:150px;height:150px}
@keyframes badgeIn{0%{transform:scale(.6);opacity:0}100%{transform:none;opacity:1}}
.bfx .bd .seg.on{animation:segOn .35s var(--ease) both .3s}
.bfx .bd .seg.on:nth-child(2){animation-delay:.42s}.bfx .bd .seg.on:nth-child(3){animation-delay:.54s}.bfx .bd .seg.on:nth-child(4){animation-delay:.66s}.bfx .bd .seg.on:nth-child(5){animation-delay:.78s}.bfx .bd .seg.on:nth-child(6){animation-delay:.9s}
@keyframes segOn{from{stroke:var(--bd-off)}}
