/* ---------- Conquistas: vidro, luz e movimento ---------- */
.bd .gls{fill:#fff;opacity:.42} .bd .edge{fill:none;stroke:#fff;stroke-opacity:.6;stroke-width:.8}
.bd.bt0 .gls{opacity:.25}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]) .bd .gls{opacity:.1} :root:not([data-theme="light"]) .bd .edge{stroke-opacity:.14}}
:root[data-theme="dark"] .bd .gls{opacity:.1} :root[data-theme="dark"] .bd .edge{stroke-opacity:.14}
#v-conquistas{position:relative;isolation:isolate}
#v-conquistas::before{content:"";position:fixed;inset:-20%;z-index:-1;pointer-events:none;background:radial-gradient(38% 30% at 18% 22%,color-mix(in srgb,#d2a12a 22%,transparent),transparent 70%),radial-gradient(34% 28% at 82% 30%,color-mix(in srgb,#2f9bd0 18%,transparent),transparent 70%),radial-gradient(40% 32% at 60% 78%,color-mix(in srgb,#8a5cf0 16%,transparent),transparent 70%);}
.cq-hero,#cqFilter,.cq-n{background:color-mix(in srgb,var(--surface) 58%,transparent)!important;-webkit-backdrop-filter:blur(20px) saturate(1.5);backdrop-filter:blur(20px) saturate(1.5);border:1px solid color-mix(in srgb,#fff 45%,var(--line));box-shadow:inset 0 1px 0 color-mix(in srgb,#fff 55%,transparent),0 10px 30px -18px rgba(0,0,0,.35)}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]) :is(.cq-hero,#cqFilter,.cq-n,.cq){border-color:color-mix(in srgb,#fff 10%,var(--line));box-shadow:inset 0 1px 0 rgba(255,255,255,.06)}}
:root[data-theme="dark"] :is(.cq-hero,#cqFilter,.cq-n,.cq){border-color:color-mix(in srgb,#fff 10%,var(--line));box-shadow:inset 0 1px 0 rgba(255,255,255,.06)}
.cq-emb{position:relative}
.cq-emb::before{content:"";position:absolute;inset:-14%;border-radius:50%;background:radial-gradient(circle,color-mix(in srgb,var(--accent) 38%,transparent),transparent 66%);animation:breathe 4.5s ease-in-out infinite;z-index:-1}
.cq-emb .bd{animation:float 6s ease-in-out infinite}
@keyframes breathe{50%{opacity:.55;transform:scale(.92)}}
@keyframes float{50%{transform:translateY(-4px)}}
.cq-grid{align-items:start;grid-auto-flow:row dense}
.cq{background:color-mix(in srgb,var(--surface) 72%,transparent);border-color:color-mix(in srgb,#fff 40%,var(--line));box-shadow:inset 0 1px 0 color-mix(in srgb,#fff 50%,transparent);transition:transform .45s cubic-bezier(.2,.8,.2,1),border-color .25s,background-color .25s;position:relative;overflow:hidden}
.cq.tilt{transform:perspective(700px) rotateX(var(--rx,0)) rotateY(var(--ry,0));transition:transform .08s linear,border-color .25s}
.cq:active{transform:scale(.975)}
.cq-sh{position:absolute;inset:0;pointer-events:none;opacity:0;transition:opacity .4s;background:radial-gradient(120px circle at var(--mx,50%) var(--my,0%),rgba(255,255,255,.10),rgba(255,255,255,.04) 45%,transparent 70%)}
.cq.tilt .cq-sh{opacity:1}
.cq-b{position:relative;display:block;isolation:isolate}
.cq.got .cq-b::before{content:"";position:absolute;inset:-6px;border-radius:50%;z-index:-1;background:radial-gradient(circle,color-mix(in srgb,var(--bd-seg) 60%,transparent),transparent 66%);transition:transform .4s var(--ease),opacity .4s}
.cq.got:hover .cq-b::before{transform:scale(1.15)}
.cq .bd .seg.on{transition:stroke-width .3s var(--ease)}
.cq.got:hover .bd .seg.on{stroke-width:4.2}
.cq-more{display:none!important;width:100%;border:0!important;padding:0!important;margin:0!important}
.cq-in{display:flex;flex-direction:column;gap:6px;margin-top:10px;padding-top:10px;border-top:1px solid var(--line);text-align:left;font-size:12px;line-height:1.35;color:var(--muted)}
.cq.open .cq-more{display:block!important}
