.cq.open .cq-in{animation:moreIn .35s cubic-bezier(.2,.8,.2,1) both}
@keyframes moreIn{from{opacity:0;transform:translateY(-6px)}}
.cq-in .ok{color:var(--best-ink)} .cq-in b{color:var(--ink);font-size:12px}
#cqGrid.anim .cq[data-a]{animation:cqIn .55s cubic-bezier(.2,.8,.2,1) both;animation-delay:calc(var(--i) * 28ms)}
@keyframes cqIn{from{opacity:0;transform:translateY(14px) scale(.97)}}
#cqHero .bbar i,#cqNext .bbar i{animation:barIn 1s cubic-bezier(.2,.8,.2,1) both .15s}
@keyframes barIn{from{transform:scaleX(0)}}
