@media (prefers-reduced-motion: reduce){#v-conquistas::before,.cq-emb::before,.cq-emb .bd,#cqGrid.anim .cq[data-a],.bfx-badge::before,#cqHero .bbar i,#cqNext .bbar i{animation:none}.cq,.cq-more{transition:none}}

