/* botão de atualização: ponto verde pulsante quando há versão nova pronta */
#updBtn{position:relative}
#updBtn .udot{position:absolute;top:4px;right:5px;width:8px;height:8px;border-radius:50%;background:var(--win);box-shadow:0 0 0 2px var(--surface);opacity:0;transform:scale(.4);transition:opacity .25s var(--ease),transform .25s var(--ease)}
#updBtn.on .udot{opacity:1;transform:none}
